CREATE ROLE app_user LOGIN;
GRANT SELECT ON orders TO app_user;
CREATE ROLE monitor LOGIN;

SET ROLE app_user;
SELECT count(*) FROM orders WHERE status = 'paid';
RESET ROLE;

SET ROLE monitor;
SELECT userid::regrole AS username, left(query, 45) AS query, calls
  FROM pg_stat_statements
 WHERE userid = 'app_user'::regrole
   AND query NOT LIKE 'SET%';
RESET ROLE;

GRANT pg_read_all_stats TO monitor;

SET ROLE monitor;
SELECT userid::regrole AS username, left(query, 45) AS query, calls
  FROM pg_stat_statements
 WHERE userid = 'app_user'::regrole
   AND query NOT LIKE 'SET%';
RESET ROLE;

SELECT pg_stat_statements_reset();

SELECT * FROM orders WHERE order_id IN (1, 2, 3);
SELECT * FROM orders WHERE order_id IN (4, 5, 6, 7);
SELECT * FROM orders WHERE order_id = 10;
select * from orders   where order_id = 11;

SELECT query, calls
  FROM pg_stat_statements
 WHERE query ILIKE 'select * from orders%'
 ORDER BY query;

